/**
 * Create a circular polygon, optionally geodesic if projection is geographic.
 * @param {import("./Circle.js").default|import("../coordinate.js").Coordinate} centerOrCircle
 * @param {number} radius
 * @param {number=} opt_sides
 * @param {number=} opt_angle
 * @param {import("../proj/Projection.js").default=} opt_projection
 * @return {Polygon}
